#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>
#include <sys/stat.h>
#include <errno.h>
#include <limits.h>
#include <unistd.h>

#define ROLE_ADMIN 0x01
#define ROLE_DEVELOPER 0x02
#define ROLE_CI_RUNNER 0x04

#define MAX_ARTIFACT_SIZE (512 * 1024 * 1024)  /* 512 MB max decompressed */
#define CHUNK_SIZE 16384
#define MAX_COMPRESSION_RATIO 100

typedef struct {
    char username[64];
    unsigned int roles;
    unsigned long quota_bytes;
} UserContext;

typedef struct {
    unsigned long compressed_size;
    unsigned long decompressed_size;
    unsigned long bytes_written;
    int ratio_check_passed;
} DecompressState;

static int authenticate_user(UserContext *ctx, const char *token) {
    /* Simplified auth - in production would verify JWT/OAuth */
    if (!token || strlen(token) < 8) return -1;
    strncpy(ctx->username, "ci-runner", sizeof(ctx->username) - 1);
    ctx->roles = ROLE_CI_RUNNER;
    ctx->quota_bytes = MAX_ARTIFACT_SIZE;
    return 0;
}

static int authorize_upload(const UserContext *ctx) {
    if (ctx->roles & (ROLE_ADMIN | ROLE_DEVELOPER | ROLE_CI_RUNNER)) {
        return 1;
    }
    return 0;
}

static int validate_compression_ratio(DecompressState *state) {
    if (state->compressed_size == 0) return 0;
    unsigned long ratio = state->decompressed_size / state->compressed_size;
    if (ratio > MAX_COMPRESSION_RATIO) {
        return 0; /* Suspicious ratio */
    }
    state->ratio_check_passed = 1;
    return 1;
}

static int check_quota_remaining(const UserContext *ctx, const DecompressState *state) {
    /* Check if we've exceeded the user's quota */
    if (state->bytes_written > ctx->quota_bytes) {
        return 0;
    }
    return 1;
}

/* Performs incremental decompression with safety checks */
static int decompress_artifact_stream(FILE *src, FILE *dst, 
                                       const UserContext *ctx,
                                       DecompressState *state) {
    z_stream strm;
    unsigned char in[CHUNK_SIZE];
    unsigned char out[CHUNK_SIZE];
    int ret;
    long comp_size;

    memset(&strm, 0, sizeof(strm));
    ret = inflateInit2(&strm, 15 + 32); /* auto-detect gzip/zlib */
    if (ret != Z_OK) return -1;

    /* First pass: read compressed size for ratio calculation */
    if (fseek(src, 0, SEEK_END) != 0) {
        inflateEnd(&strm);
        return -1;
    }
    comp_size = ftell(src);
    if (comp_size < 0) {
        inflateEnd(&strm);
        return -1;
    }
    if (fseek(src, 0, SEEK_SET) != 0) {
        inflateEnd(&strm);
        return -1;
    }
    state->compressed_size = (unsigned long)comp_size;

    do {
        strm.avail_in = fread(in, 1, CHUNK_SIZE, src);
        if (ferror(src)) {
            inflateEnd(&strm);
            return -1;
        }
        if (strm.avail_in == 0) break;
        strm.next_in = in;

        do {
            strm.avail_out = CHUNK_SIZE;
            strm.next_out = out;
            ret = inflate(&strm, Z_NO_FLUSH);

            if (ret == Z_NEED_DICT || ret == Z_DATA_ERROR || ret == Z_MEM_ERROR) {
                inflateEnd(&strm);
                return -1;
            }

            unsigned have = CHUNK_SIZE - strm.avail_out;
            state->decompressed_size += have;

            /* Ratio check performed once after first chunk */
            if (!state->ratio_check_passed && state->decompressed_size > CHUNK_SIZE) {
                if (!validate_compression_ratio(state)) {
                    fprintf(stderr, "[SECURITY] Compression ratio exceeded limit\n");
                    inflateEnd(&strm);
                    return -2;
                }
            }

            /* Quota enforcement uses bytes_written, updated AFTER write */
            if (fwrite(out, 1, have, dst) != have) {
                inflateEnd(&strm);
                return -1;
            }
            state->bytes_written += have;

            /* Check quota AFTER updating bytes_written */
            if (!check_quota_remaining(ctx, state)) {
                fprintf(stderr, "[QUOTA] User %s exceeded quota\n", ctx->username);
                inflateEnd(&strm);
                return -3;
            }

        } while (strm.avail_out == 0);

    } while (ret != Z_STREAM_END);

    inflateEnd(&strm);
    return (ret == Z_STREAM_END) ? 0 : -1;
}

int process_ci_artifact(const char *input_path, const char *output_dir, 
                        const char *auth_token) {
    UserContext ctx;
    DecompressState state;
    char output_path[PATH_MAX];
    FILE *src = NULL, *dst = NULL;
    int result = -1;

    memset(&ctx, 0, sizeof(ctx));
    memset(&state, 0, sizeof(state));

    if (authenticate_user(&ctx, auth_token) != 0) {
        fprintf(stderr, "Authentication failed\n");
        return -1;
    }

    if (!authorize_upload(&ctx)) {
        fprintf(stderr, "Authorization denied for user %s\n", ctx.username);
        return -1;
    }

    /* All roles subject to the same decompression quota */
    if (ctx.roles & ROLE_CI_RUNNER) {
        ctx.quota_bytes = MAX_ARTIFACT_SIZE; /* CI runners use standard limit */
    }

    snprintf(output_path, sizeof(output_path), "%s/artifact.bin", output_dir);

    src = fopen(input_path, "rb");
    if (!src) {
        fprintf(stderr, "Cannot open input: %s\n", strerror(errno));
        return -1;
    }

    dst = fopen(output_path, "wb");
    if (!dst) {
        fprintf(stderr, "Cannot open output: %s\n", strerror(errno));
        fclose(src);
        return -1;
    }

    result = decompress_artifact_stream(src, dst, &ctx, &state);

    fclose(src);
    fclose(dst);

    if (result == 0) {
        printf("[OK] Artifact decompressed: %lu bytes\n", state.bytes_written);
    } else {
        unlink(output_path);
    }

    return result;
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <artifact.gz> <output_dir> <auth_token>\n", argv[0]);
        return 1;
    }
    return process_ci_artifact(argv[1], argv[2], argv[3]);
}
